package com.bank.roster;

import java.util.*;
import java.util.logging.*;

public class RosterDemo {
    private static final Logger log = Logger.getLogger("Roster");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh"),
            new Employee(2L, "Priya"),
            new Employee(3L, "Amit")
        );
        RosterService service = new RosterService();
        String line = service.joinNames(staff);
        log.info(() -> "Team roster: " + line);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    Employee(Long id, String name) { this.id = id; this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/RosterService.java ───
class RosterService {
    // reduce from "" and append with ", " only when the running string is non-empty.
    String joinNames(List<Employee> employees) {
        return employees.stream()
            .map(Employee::getName)
            .reduce("",
                    (running, name) -> running.isEmpty() ? name : running + ", " + name,
                    (s1, s2) -> s1.isEmpty() ? s2 : (s2.isEmpty() ? s1 : s1 + ", " + s2));
    }
}
